import { getCachedProducts } from "@/lib/products";
import { revalidateTag, refresh } from "next/cache";

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    "use server";
    revalidateTag("products", { expire: 0 });
    refresh();
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "2rem" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "2rem" }}>
        <h1>Product Catalog (Admin)</h1>
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: "0.5rem 1rem",
              backgroundColor: "#0070f3",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer"
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div style={{ border: "1px solid #eaeaea", borderRadius: "8px", overflow: "hidden" }}>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ backgroundColor: "#fafafa", borderBottom: "1px solid #eaeaea" }}>
              <th style={{ padding: "1rem", textAlign: "left" }}>ID</th>
              <th style={{ padding: "1rem", textAlign: "left" }}>Product Name</th>
              <th style={{ padding: "1rem", textAlign: "right" }}>Price</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} style={{ borderBottom: "1px solid #eaeaea" }}>
                <td style={{ padding: "1rem" }}>{product.id}</td>
                <td style={{ padding: "1rem" }}>{product.name}</td>
                <td style={{ padding: "1rem", textAlign: "right" }}>${product.price}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p style={{ marginTop: "1rem", color: "#666", fontSize: "0.875rem" }}>
        Products are cached for fast browsing. Click "Sync latest catalog" to refresh data from upstream sources.
      </p>
    </div>
  );
}

