export async function getAllProducts() {
  // Simulate database delay (mimicking ERP/PIM query)
  await new Promise(resolve => setTimeout(resolve, 100));

  // Simulate fresh data from upstream systems
  // In production, this would query your ERP/PIM/inventory system
  const timestamp = new Date().toLocaleTimeString();

  return [
    { id: 1, name: 'Laptop', price: 999, lastSync: timestamp },
    { id: 2, name: 'Phone', price: 699, lastSync: timestamp },
    { id: 3, name: 'Tablet', price: 499, lastSync: timestamp },
    { id: 4, name: 'Headphones', price: 199, lastSync: timestamp },
    { id: 5, name: 'Watch', price: 299, lastSync: timestamp }
  ];
}

